import { PDFDocument, StandardFonts, degrees, rgb } from 'pdf-lib';

/**
 * Mandatory, visible warning on EVERY page generated by the synthetic QA
 * service. This is not an official document, regardless of template origin.
 */
export async function watermarkQaSample(pdfBytes: Uint8Array): Promise<Uint8Array> {
  const pdf = await PDFDocument.load(pdfBytes);
  const font = await pdf.embedFont(StandardFonts.HelveticaBold);
  const warning = 'AMOSTRA - DADOS FICTICIOS - NAO UTILIZAR';
  for (const page of pdf.getPages()) {
    const { width, height } = page.getSize();
    page.drawText(warning, {
      x: 35, y: height * 0.48, size: 16, font, rotate: degrees(18),
      color: rgb(0.7, 0.12, 0.12), opacity: 0.45,
    });
    page.drawRectangle({
      x: 0, y: 0, width, height: 24, color: rgb(1, 0.93, 0.9), opacity: 0.95,
    });
    page.drawText(warning, {
      x: 20, y: 8, size: 9, font, color: rgb(0.6, 0.08, 0.08),
    });
  }
  return pdf.save({ useObjectStreams: false });
}
